from __future__ import annotations

import asyncio
import hashlib
import struct
import wave
from pathlib import Path
from urllib.parse import unquote, urlparse

from src.operations.media_models import MediaProbeResult, MediaSource, MediaType


class MediaProbeError(Exception):
    def __init__(self, code: str, status_code: int = 422) -> None:
        super().__init__(code)
        self.code = code
        self.status_code = status_code


class LocalMediaProbe:
    """Probe immutable local media mounted beneath one configured root."""

    def __init__(self, root: Path, max_bytes: int, max_duration_seconds: int) -> None:
        self.root = root.resolve()
        self.max_bytes = max_bytes
        self.max_duration_ms = max_duration_seconds * 1000

    async def probe(self, source: MediaSource) -> MediaProbeResult:
        return await asyncio.to_thread(self._probe, source)

    def _probe(self, source: MediaSource) -> MediaProbeResult:
        path = self._resolve(source.uri)
        try:
            size = path.stat().st_size
        except OSError as exc:
            raise MediaProbeError("source_unavailable") from exc
        if size <= 0:
            raise MediaProbeError("corrupt_media")
        if size > self.max_bytes:
            raise MediaProbeError("media_too_large", status_code=413)

        digest = hashlib.sha256()
        try:
            with path.open("rb") as handle:
                while chunk := handle.read(1024 * 1024):
                    digest.update(chunk)
        except OSError as exc:
            raise MediaProbeError("source_unavailable") from exc
        checksum = digest.hexdigest()
        if checksum != source.checksum_sha256:
            raise MediaProbeError("checksum_mismatch")

        if source.media_type == MediaType.WAV:
            duration_ms = self._probe_wav(path)
        elif source.media_type == MediaType.MP3:
            duration_ms = self._probe_mp3(path, size)
        elif source.media_type == MediaType.MP4:
            duration_ms = self._probe_mp4(path, size)
        else:
            raise MediaProbeError("unsupported_media_type", status_code=415)

        if duration_ms > self.max_duration_ms:
            raise MediaProbeError("media_too_long")
        return MediaProbeResult(
            checksum_sha256=checksum,
            detected_media_type=source.media_type,
            duration_ms=duration_ms,
            size_bytes=size,
        )

    def _resolve(self, uri: str) -> Path:
        parsed = urlparse(uri)
        if parsed.scheme != "file" or parsed.netloc not in {"", "localhost"}:
            raise MediaProbeError("unsupported_uri_scheme", status_code=415)
        try:
            candidate = Path(unquote(parsed.path)).resolve(strict=True)
        except (OSError, RuntimeError) as exc:
            raise MediaProbeError("source_unavailable") from exc
        if not candidate.is_file() or not candidate.is_relative_to(self.root):
            raise MediaProbeError("source_outside_media_root")
        return candidate

    @staticmethod
    def _probe_wav(path: Path) -> int:
        try:
            with wave.open(str(path), "rb") as media:
                frames = media.getnframes()
                rate = media.getframerate()
                if frames <= 0 or rate <= 0 or media.getnchannels() <= 0:
                    raise MediaProbeError("corrupt_media")
                return max(1, round(frames / rate * 1000))
        except (wave.Error, EOFError, OSError) as exc:
            raise MediaProbeError("corrupt_media") from exc

    @staticmethod
    def _probe_mp3(path: Path, size: int) -> int:
        try:
            with path.open("rb") as handle:
                sample = handle.read(min(size, 128 * 1024))
        except OSError as exc:
            raise MediaProbeError("source_unavailable") from exc

        offset = 0
        if sample.startswith(b"ID3") and len(sample) >= 10:
            encoded = sample[6:10]
            if any(byte & 0x80 for byte in encoded):
                raise MediaProbeError("corrupt_media")
            offset = 10 + sum(byte << shift for byte, shift in zip(encoded, (21, 14, 7, 0)))

        bitrate_v1_l3 = (0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320, 0)
        bitrate_v2_l3 = (0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160, 0)
        for index in range(offset, max(offset, len(sample) - 3)):
            header = int.from_bytes(sample[index : index + 4], "big")
            if header >> 21 != 0x7FF:
                continue
            version_bits = (header >> 19) & 0b11
            layer_bits = (header >> 17) & 0b11
            bitrate_index = (header >> 12) & 0b1111
            sample_rate_index = (header >> 10) & 0b11
            if version_bits == 0b01 or layer_bits != 0b01 or sample_rate_index == 0b11:
                continue
            bitrate = (bitrate_v1_l3 if version_bits == 0b11 else bitrate_v2_l3)[bitrate_index]
            if bitrate:
                audio_bytes = max(1, size - index)
                return max(1, round(audio_bytes * 8 / (bitrate * 1000) * 1000))
        raise MediaProbeError("corrupt_media")

    @classmethod
    def _probe_mp4(cls, path: Path, size: int) -> int:
        try:
            with path.open("rb") as handle:
                boxes = list(cls._boxes(handle, 0, size))
                if not any(kind == b"ftyp" for kind, _, _ in boxes):
                    raise MediaProbeError("corrupt_media")
                for kind, payload_start, payload_end in boxes:
                    if kind != b"moov":
                        continue
                    children = cls._boxes(handle, payload_start, payload_end)
                    for child_kind, child_start, child_end in children:
                        if child_kind == b"mvhd":
                            handle.seek(child_start)
                            payload = handle.read(min(child_end - child_start, 40))
                            return cls._mvhd_duration(payload)
        except (OSError, ValueError, struct.error) as exc:
            raise MediaProbeError("corrupt_media") from exc
        raise MediaProbeError("corrupt_media")

    @staticmethod
    def _boxes(handle, start: int, end: int):
        position = start
        while position + 8 <= end:
            handle.seek(position)
            header = handle.read(8)
            if len(header) != 8:
                raise ValueError("truncated box")
            box_size, kind = struct.unpack(">I4s", header)
            header_size = 8
            if box_size == 1:
                extended = handle.read(8)
                if len(extended) != 8:
                    raise ValueError("truncated extended box")
                box_size = struct.unpack(">Q", extended)[0]
                header_size = 16
            elif box_size == 0:
                box_size = end - position
            if box_size < header_size or position + box_size > end:
                raise ValueError("invalid box size")
            yield kind, position + header_size, position + box_size
            position += box_size

    @staticmethod
    def _mvhd_duration(payload: bytes) -> int:
        if len(payload) < 20:
            raise ValueError("truncated mvhd")
        version = payload[0]
        if version == 0:
            timescale = struct.unpack(">I", payload[12:16])[0]
            duration = struct.unpack(">I", payload[16:20])[0]
        elif version == 1 and len(payload) >= 32:
            timescale = struct.unpack(">I", payload[20:24])[0]
            duration = struct.unpack(">Q", payload[24:32])[0]
        else:
            raise ValueError("unsupported mvhd")
        if timescale <= 0 or duration <= 0:
            raise ValueError("invalid duration")
        return max(1, round(duration / timescale * 1000))

from __future__ import annotations

from datetime import datetime, timezone
from enum import Enum
from typing import Any, Dict, Optional
from urllib.parse import urlparse

from pydantic import BaseModel, Field, field_validator, model_validator


def utc_now() -> datetime:
    return datetime.now(timezone.utc)


class MediaType(str, Enum):
    WAV = "audio/wav"
    MP3 = "audio/mpeg"
    MP4 = "video/mp4"


class MediaOperationState(str, Enum):
    QUEUED = "queued"
    RUNNING = "running"
    SUCCEEDED = "succeeded"
    FAILED = "failed"
    CANCELED = "canceled"


class MediaStageName(str, Enum):
    PROBE = "probe"
    TRANSCRIPTION = "transcription"
    DIARIZATION = "diarization"
    SUMMARY = "summary"


class MediaStageState(str, Enum):
    PENDING = "pending"
    RUNNING = "running"
    SUCCEEDED = "succeeded"
    FAILED = "failed"
    CANCELED = "canceled"


class SpeakerState(str, Enum):
    IDENTIFIED = "identified"
    UNKNOWN = "unknown"


class MediaSource(BaseModel):
    uri: str = Field(min_length=1, max_length=2048)
    checksum_sha256: str = Field(pattern=r"^[a-fA-F0-9]{64}$")
    media_type: MediaType
    language_hint: Optional[str] = Field(default=None, min_length=2, max_length=35)

    @field_validator("uri")
    @classmethod
    def validate_uri(cls, value: str) -> str:
        parsed = urlparse(value)
        if not parsed.scheme:
            raise ValueError("uri must be absolute")
        if parsed.username or parsed.password or parsed.query or parsed.fragment:
            raise ValueError("uri credentials, query, and fragment are not supported")
        return value

    @field_validator("checksum_sha256")
    @classmethod
    def normalize_checksum(cls, value: str) -> str:
        return value.lower()


class MediaOperationOptions(BaseModel):
    max_attempts: int = Field(default=3, ge=1, le=10)
    retention_seconds: int = Field(default=7 * 24 * 60 * 60, ge=300, le=30 * 24 * 60 * 60)


class MediaOperationRequest(BaseModel):
    source: MediaSource
    options: MediaOperationOptions = Field(default_factory=MediaOperationOptions)


class MediaProbeResult(BaseModel):
    checksum_sha256: str
    detected_media_type: MediaType
    duration_ms: int = Field(gt=0)
    size_bytes: int = Field(gt=0)


class TimeRange(BaseModel):
    start_ms: int = Field(ge=0)
    end_ms: int = Field(gt=0)

    @model_validator(mode="after")
    def validate_order(self):
        if self.end_ms <= self.start_ms:
            raise ValueError("end_ms must be greater than start_ms")
        return self


class TranscriptSegment(TimeRange):
    text: str = Field(min_length=1, max_length=20_000)


class TranscriptionArtifact(BaseModel):
    language: str = Field(min_length=2, max_length=35)
    language_confidence: Optional[float] = Field(default=None, ge=0, le=1)
    segments: list[TranscriptSegment] = Field(min_length=1)


class DiarizedSegment(TranscriptSegment):
    speaker_state: SpeakerState
    speaker_label: Optional[str] = Field(default=None, min_length=1, max_length=80)
    speaker_confidence: Optional[float] = Field(default=None, ge=0, le=1)

    @model_validator(mode="after")
    def validate_speaker(self):
        if self.speaker_state == SpeakerState.UNKNOWN:
            if self.speaker_label is not None or self.speaker_confidence is not None:
                raise ValueError("unknown speakers cannot have a label or confidence")
        elif self.speaker_label is None or self.speaker_confidence is None:
            raise ValueError("identified speakers require a label and confidence")
        return self


class DiarizationArtifact(BaseModel):
    segments: list[DiarizedSegment] = Field(min_length=1)


class SummaryPoint(BaseModel):
    text: str = Field(min_length=1, max_length=4_000)
    source_timecodes: list[TimeRange] = Field(min_length=1)


class SummaryArtifact(BaseModel):
    points: list[SummaryPoint] = Field(min_length=1)


class ModelIdentity(BaseModel):
    provider: str = Field(min_length=1, max_length=120)
    model: str = Field(min_length=1, max_length=200)
    version: str = Field(min_length=1, max_length=120)


class StageProvenance(ModelIdentity):
    input_checksum_sha256: str = Field(pattern=r"^[a-f0-9]{64}$")


class MediaStageRecord(BaseModel):
    state: MediaStageState = MediaStageState.PENDING
    attempts: int = 0
    output: Optional[Dict[str, Any]] = None
    provenance: Optional[StageProvenance] = None
    error_code: Optional[str] = Field(default=None, max_length=80)
    started_at: Optional[datetime] = None
    completed_at: Optional[datetime] = None


def initial_stages() -> Dict[MediaStageName, MediaStageRecord]:
    return {stage: MediaStageRecord() for stage in MediaStageName}


class MediaOperationResult(BaseModel):
    source_checksum_sha256: str
    duration_ms: int
    language: str
    language_confidence: Optional[float] = None
    transcript: list[DiarizedSegment]
    summary: list[SummaryPoint]
    provenance: Dict[MediaStageName, StageProvenance]


class MediaOperationRecord(BaseModel):
    operation_id: str
    state: MediaOperationState = MediaOperationState.QUEUED
    source: MediaSource
    options: MediaOperationOptions
    probe: MediaProbeResult
    attempts: int = 0
    stages: Dict[MediaStageName, MediaStageRecord] = Field(default_factory=initial_stages)
    result: Optional[MediaOperationResult] = None
    error_code: Optional[str] = Field(default=None, max_length=80)
    created_at: datetime = Field(default_factory=utc_now)
    updated_at: datetime = Field(default_factory=utc_now)


class MediaOperationSubmission(BaseModel):
    operation_id: str
    state: MediaOperationState
    status_url: str


class MediaRunOutcome(BaseModel):
    state: MediaOperationState
    result: Optional[Dict[str, Any]] = None
    error_code: Optional[str] = None
    retry: bool = False

